float* allocSamples(uint64_t nFrames, uint64_t frameLen) {
    constexpr uint64_t kMaxBytes = 1ull << 30;   // 1 GiB
    constexpr uint64_t kMaxElems = kMaxBytes / sizeof(float);
    if (nFrames == 0 || frameLen == 0) return nullptr;
    // check before multiplying: nFrames * frameLen <= kMaxElems
    if (nFrames > kMaxElems / frameLen) return nullptr;
    uint64_t n = nFrames * frameLen;   // cannot overflow now
    return new (std::nothrow) float[n];
}

